mapper.select:
SELECT mu.id as userId, mu.avatar_url, mu.nickname
FROM member_user_follow fs
         INNER JOIN member_user mu ON fs.user_id = mu.id
WHERE   fs.status = 0 and fs.target_id = #{reqVO.authorId} and fs.target_type = 1

    AND fs.create_time >= #{reqVO.beginTime}


    AND fs.create_time <= #{reqVO.endTime}

SELECT target_id as targetId, COUNT(*) AS fans FROM member_user_follow WHERE `status` = 0 and target_type = #{targetType}
AND target_id IN
#{id}
GROUP BY target_id

SELECT COUNT(*)
FROM member_user_follow
WHERE target_type =#{targetType}
  AND target_id = #{targetId}
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}

SELECT COUNT(*)
FROM member_user_follow
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND status = 1
  AND update_time >= #{startTime}
  AND update_time <= #{endTime}

SELECT
    DATE(create_time) AS bizDate,
    COUNT(*) AS newFans
FROM member_user_follow
WHERE
    target_type = #{targetType}
  AND target_id = #{targetId}
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
GROUP BY DATE(create_time)

SELECT
    DATE(update_time) AS bizDate,
    COUNT(*) AS cancelFans
FROM member_user_follow
WHERE
    target_type = #{targetType}
  AND target_id = #{targetId}
  AND status =1
  AND update_time >= #{startTime}
  AND update_time <= #{endTime}
GROUP BY DATE(update_time)

SELECT target_id AS authorId, COUNT(*) AS followCount FROM member_user_follow WHERE target_type = 1 and `status` = 0 AND target_id IN
#{id}
AND create_time >= #{startDate} AND create_time <= #{endDate} GROUP BY target_id

SELECT target_id AS authorId, COUNT(*) AS followCount FROM member_user_follow WHERE target_type = 1 and `status` = 0 AND target_id IN
#{id}
AND create_time <= #{endDate} GROUP BY target_id

SELECT mu.id AS member_id, mu.nickname, mu.mobile FROM member_user_follow fs INNER JOIN member_user mu ON fs.user_id = mu.id WHERE fs.STATUS = 0 AND fs.user_status = 1 AND fs.target_type = 1 AND fs.target_id = #{reqVO.authorId}
AND mu.nickname LIKE CONCAT('%', #{reqVO.nickname}, '%')
AND mu.id IN
#{id}

SELECT fs.* FROM member_user_follow fs
INNER JOIN author_user au ON au.id = fs.target_id AND JSON_CONTAINS(au.device_types, CONCAT('"', #{deviceType}, '"')) AND au.status = 0
WHERE fs.status = 0 AND fs.user_id = #{userId} AND fs.target_type = #{targetType}

SELECT fs.target_id FROM member_user_follow fs
INNER JOIN author_user au ON au.id = fs.target_id AND JSON_CONTAINS(au.device_types, CONCAT('"', #{deviceType}, '"')) AND au.status = 0
WHERE fs.status = 0 AND fs.user_id = #{userId} AND fs.target_type = #{targetType}
